498	/// Canonicalise a write target. If the file doesn't exist yet, canonicalise the
499	/// parent directory and re-attach the final component. Bails if neither the
500	/// file nor its parent directory exists.
501	fn canonicalize_for_write(file: &Path) -> Result<PathBuf> {
502	    if let Ok(c) = file.canonicalize() {
503	        return Ok(c);
504	    }
505	    let parent = file
506	        .parent()
507	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
508	        .unwrap_or(Path::new("."));
509	    let parent_canonical = parent
510	        .canonicalize()
511	        .with_context(|| format!("parent directory {} not found", parent.display()))?;
512	    let name = file
513	        .file_name()
514	        .ok_or_else(|| anyhow!("write target `{}` has no file name", file.display()))?;
515	    Ok(parent_canonical.join(name))
516	}
517	
518	/// Return the git repository top-level directory (canonical), or the current
519	/// working directory if git is unavailable or CWD is not inside a repo.
520	fn repo_or_cwd_root() -> Result<PathBuf> {
521	    let cwd = std::env::current_dir().context("reading current working directory")?;
522	    match std::process::Command::new("git")
523	        .args(["rev-parse", "--show-toplevel"])
524	        .output()
525	    {
526	        Ok(out) if out.status.success() => {
527	            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
528	            if s.is_empty() {
529	                Ok(cwd)
530	            } else {
531	                let p = PathBuf::from(s);
532	                Ok(p.canonicalize().unwrap_or(p))
533	            }
534	        }
535	        _ => Ok(cwd.canonicalize().unwrap_or(cwd)),
536	    }
537	}
