539	/// Write the TOML document and (unless suppressed) also write the `<file>.sha256`
540	/// sidecar. The sidecar is hashed from the bytes that actually landed on disk
541	/// after the atomic rename, so the digest always reflects the serialiser's
542	/// output. Failure to write the sidecar is reported as a stderr warning but
543	/// does not fail the outer write — the primary data is already durable.
544	fn write_toml_with_sidecar(
545	    path: &Path,
546	    value: &TomlValue,
547	    integrity: IntegrityOpts,
548	) -> Result<()> {
549	    write_toml(path, value)?;
550	    if integrity.write_sidecar
551	        && let Err(e) = write_integrity_sidecar(path)
552	    {
553	        eprintln!(
554	            "tomlctl: warning: wrote {} but failed to refresh integrity sidecar: {:#}",
555	            path.display(),
556	            e
557	        );
558	    }
559	    Ok(())
560	}
561	
562	fn write_toml(path: &Path, value: &TomlValue) -> Result<()> {
563	    let parent = path
564	        .parent()
565	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
566	        .unwrap_or(Path::new("."));
567	    let serialized = toml::to_string_pretty(value).context("serialising TOML")?;
568	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
569	        .with_context(|| format!("creating temp file in {}", parent.display()))?;
570	    std::io::Write::write_all(&mut tmp, serialized.as_bytes())
571	        .with_context(|| format!("writing temp file for {}", path.display()))?;
572	    tmp.persist(path)
573	        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
574	    Ok(())
575	}
