584	/// Lowercase hex encoding of a byte slice. Replaces the `{:x}` formatter for
585	/// digest outputs, which stopped implementing `LowerHex` in sha2 0.11.
586	fn hex_lower(bytes: &[u8]) -> String {
587	    use std::fmt::Write;
588	    let mut s = String::with_capacity(bytes.len() * 2);
589	    for b in bytes {
590	        let _ = write!(s, "{:02x}", b);
591	    }
592	    s
593	}
594	
595	/// Compute the SHA-256 hex digest of a file's current bytes.
596	fn sha256_hex_of_file(file: &Path) -> Result<String> {
597	    let bytes =
598	        fs::read(file).with_context(|| format!("reading {} for hashing", file.display()))?;
599	    Ok(hex_lower(&Sha256::digest(&bytes)))
600	}
601	
602	/// Write the sidecar for `file`. Format mirrors `sha256sum` output exactly:
603	/// `<lowercase-hex-64>  <basename>\n`.
604	///
605	/// The sidecar is written via a tempfile in the same directory, then renamed,
606	/// so a concurrent reader never sees a half-written sidecar.
607	fn write_integrity_sidecar(file: &Path) -> Result<()> {
608	    let hex = sha256_hex_of_file(file)?;
609	    let sidecar = sidecar_path(file);
610	    let basename = file
611	        .file_name()
612	        .ok_or_else(|| anyhow!("target `{}` has no file name", file.display()))?
613	        .to_string_lossy()
614	        .into_owned();
615	    let contents = format!("{}  {}\n", hex, basename);
616	    let parent = sidecar
617	        .parent()
618	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
619	        .unwrap_or(Path::new("."));
620	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
621	        .with_context(|| format!("creating temp file for sidecar in {}", parent.display()))?;
622	    std::io::Write::write_all(&mut tmp, contents.as_bytes())
623	        .with_context(|| format!("writing sidecar temp file for {}", sidecar.display()))?;
624	    tmp.persist(&sidecar).map_err(|e| {
625	        anyhow!(
626	            "atomic rename to {} failed: {}",
627	            sidecar.display(),
628	            e.error
629	        )
630	    })?;
631	    Ok(())
632	}
