688	fn navigate<'a>(root: &'a TomlValue, path: &str) -> Option<&'a TomlValue> {
689	    let mut cur = root;
690	    for part in path.split('.') {
691	        cur = cur.as_table()?.get(part)?;
692	    }
693	    Some(cur)
694	}
