718	fn parse_scalar(input: &str, explicit: Option<ScalarType>) -> Result<TomlValue> {
719	    let ty = explicit.unwrap_or_else(|| infer_type(input));
720	    match ty {
721	        ScalarType::Str => Ok(TomlValue::String(input.to_string())),
722	        ScalarType::Int => Ok(TomlValue::Integer(
723	            input
724	                .parse::<i64>()
725	                .with_context(|| format!("`{}` is not a valid int", input))?,
726	        )),
727	        ScalarType::Float => Ok(TomlValue::Float(
728	            input
729	                .parse::<f64>()
730	                .with_context(|| format!("`{}` is not a valid float", input))?,
731	        )),
732	        ScalarType::Bool => Ok(TomlValue::Boolean(
733	            input
734	                .parse::<bool>()
735	                .with_context(|| format!("`{}` is not a valid bool", input))?,
736	        )),
737	        ScalarType::Date | ScalarType::Datetime => {
738	            let dt: toml::value::Datetime = input
739	                .parse()
740	                .with_context(|| format!("`{}` is not a valid TOML datetime", input))?;
741	            Ok(TomlValue::Datetime(dt))
742	        }
743	    }
744	}
745	
746	fn infer_type(s: &str) -> ScalarType {
747	    if s == "true" || s == "false" {
748	        ScalarType::Bool
749	    } else if looks_like_date(s) {
750	        ScalarType::Date
751	    } else if s.parse::<i64>().is_ok() {
752	        ScalarType::Int
753	    } else {
754	        ScalarType::Str
755	    }
756	}
757	
758	fn looks_like_date(s: &str) -> bool {
759	    let b = s.as_bytes();
760	    b.len() == 10
761	        && b[4] == b'-'
762	        && b[7] == b'-'
763	        && b[..4].iter().all(|c| c.is_ascii_digit())
764	        && b[5..7].iter().all(|c| c.is_ascii_digit())
765	        && b[8..10].iter().all(|c| c.is_ascii_digit())
766	}
767	
768	fn toml_to_json(v: &TomlValue) -> JsonValue {
769	    match v {
770	        TomlValue::String(s) => JsonValue::String(s.clone()),
771	        TomlValue::Integer(i) => JsonValue::from(*i),
772	        TomlValue::Float(f) => serde_json::Number::from_f64(*f)
773	            .map(JsonValue::Number)
774	            .unwrap_or(JsonValue::Null),
775	        TomlValue::Boolean(b) => JsonValue::Bool(*b),
776	        TomlValue::Datetime(dt) => JsonValue::String(dt.to_string()),
777	        TomlValue::Array(a) => JsonValue::Array(a.iter().map(toml_to_json).collect()),
778	        TomlValue::Table(t) => {
779	            let mut m = serde_json::Map::new();
780	            for (k, v) in t.iter() {
781	                m.insert(k.clone(), toml_to_json(v));
782	            }
783	            JsonValue::Object(m)
784	        }
785	    }
786	}
