838	/// Bundle of optional per-field filters for `items list`. All populated filters
839	/// combine via logical AND; unset filters are no-ops.
840	#[derive(Clone, Copy, Default)]
841	struct ListFilters<'a> {
842	    status: Option<&'a str>,
843	    category: Option<&'a str>,
844	    newer_than: Option<&'a toml::value::Datetime>,
845	    file_filter: Option<&'a str>,
846	}
847	
848	fn items_list(doc: &TomlValue, filters: ListFilters<'_>) -> Result<Vec<JsonValue>> {
849	    let items = items_array(doc)?;
850	    let mut out = Vec::new();
851	    for item in items {
852	        let tbl = match item.as_table() {
853	            Some(t) => t,
854	            None => continue,
855	        };
856	        if let Some(want) = filters.status {
857	            let cur = tbl.get("status").and_then(|v| v.as_str()).unwrap_or("");
858	            if cur != want {
859	                continue;
860	            }
861	        }
862	        if let Some(want) = filters.category {
863	            let cur = tbl.get("category").and_then(|v| v.as_str()).unwrap_or("");
864	            if cur != want {
865	                continue;
866	            }
867	        }
868	        if let Some(want) = filters.file_filter {
869	            let cur = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
870	            if cur != want {
871	                continue;
872	            }
873	        }
874	        if let Some(threshold) = filters.newer_than {
875	            let ff = match tbl.get("first_flagged").and_then(|v| v.as_datetime()) {
876	                Some(d) => d,
877	                None => continue,
878	            };
879	            if !datetime_gt(ff, threshold) {
880	                continue;
881	            }
882	        }
883	        out.push(toml_to_json(item));
884	    }
885	    Ok(out)
886	}
