988	fn apply_single_op(doc: &mut TomlValue, op: &JsonValue) -> Result<()> {
989	    let obj = op
990	        .as_object()
991	        .ok_or_else(|| anyhow!("op must be a JSON object"))?;
992	    let op_name = obj
993	        .get("op")
994	        .and_then(|v| v.as_str())
995	        .ok_or_else(|| anyhow!("op missing `op` field"))?;
996	    match op_name {
997	        "add" => {
998	            let json = obj
999	                .get("json")
1000	                .ok_or_else(|| anyhow!("add op missing `json` field"))?;
1001	            items_add_value(doc, json)
1002	        }
1003	        "update" => {
1004	            let id = obj
1005	                .get("id")
1006	                .and_then(|v| v.as_str())
1007	                .ok_or_else(|| anyhow!("update op missing `id` field"))?;
1008	            let json = obj
1009	                .get("json")
1010	                .ok_or_else(|| anyhow!("update op missing `json` field"))?;
1011	            let unset: Vec<String> = match obj.get("unset") {
1012	                None | Some(JsonValue::Null) => Vec::new(),
1013	                Some(JsonValue::Array(a)) => {
1014	                    let mut out = Vec::with_capacity(a.len());
1015	                    for entry in a {
1016	                        match entry {
1017	                            JsonValue::String(s) => out.push(s.clone()),
1018	                            other => bail!(
1019	                                "update op `unset` must be an array of strings, got element `{}`",
1020	                                other
1021	                            ),
1022	                        }
1023	                    }
1024	                    out
1025	                }
1026	                Some(other) => bail!(
1027	                    "update op `unset` must be a JSON array of strings, got `{}`",
1028	                    other
1029	                ),
1030	            };
1031	            items_update_value(doc, id, json, &unset)
1032	        }
1033	        "remove" => {
1034	            let id = obj
1035	                .get("id")
1036	                .and_then(|v| v.as_str())
1037	                .ok_or_else(|| anyhow!("remove op missing `id` field"))?;
1038	            items_remove(doc, id)
1039	        }
1040	        other => bail!("unknown op `{}`", other),
1041	    }
1042	}
