1101	fn find_duplicates_tier_a(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1102	    // Group under two key-spaces:
1103	    //   by (file, symbol) when symbol is non-empty
1104	    //   by (file, summary) otherwise
1105	    // An item appears in exactly one group (either symbol-keyed or summary-keyed).
1106	    let mut by_symbol: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1107	    let mut by_summary: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1108	    for (i, item) in items.iter().enumerate() {
1109	        let tbl = match item.as_table() {
1110	            Some(t) => t,
1111	            None => continue,
1112	        };
1113	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1114	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1115	        if !symbol.is_empty() {
1116	            by_symbol
1117	                .entry((file.to_string(), symbol.to_string()))
1118	                .or_default()
1119	                .push(i);
1120	        } else {
1121	            let summary = tbl.get("summary").and_then(|v| v.as_str()).unwrap_or("");
1122	            by_summary
1123	                .entry((file.to_string(), summary.to_string()))
1124	                .or_default()
1125	                .push(i);
1126	        }
1127	    }
1128	    let mut out = Vec::new();
1129	    for ((file, symbol), idxs) in &by_symbol {
1130	        if idxs.len() < 2 {
1131	            continue;
1132	        }
1133	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1134	        out.push(dup_group_json(
1135	            "A",
1136	            &format!("file={} symbol={}", file, symbol),
1137	            &refs,
1138	        ));
1139	    }
1140	    for ((file, summary), idxs) in &by_summary {
1141	        if idxs.len() < 2 {
1142	            continue;
1143	        }
1144	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1145	        out.push(dup_group_json(
1146	            "A",
1147	            &format!("file={} summary={}", file, summary),
1148	            &refs,
1149	        ));
1150	    }
1151	    Ok(out)
1152	}
1153	
1154	fn find_duplicates_tier_b(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1155	    let mut groups: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1156	    for (i, item) in items.iter().enumerate() {
1157	        let tbl = match item.as_table() {
1158	            Some(t) => t,
1159	            None => continue,
1160	        };
1161	        let file = tbl.get("file").and_then(|v| v.as_str()).unwrap_or("");
1162	        let summary = tbl.get("summary").and_then(|v| v.as_str()).unwrap_or("");
1163	        let severity = tbl.get("severity").and_then(|v| v.as_str()).unwrap_or("");
1164	        let category = tbl.get("category").and_then(|v| v.as_str()).unwrap_or("");
1165	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1166	        let canonical = format!(
1167	            "{}|{}|{}|{}|{}",
1168	            file, summary, severity, category, symbol
1169	        );
1170	        let full = hex_lower(&Sha256::digest(canonical.as_bytes()));
1171	        let short = full[..16].to_string();
1172	        let basename = Path::new(file)
1173	            .file_name()
1174	            .map(|s| s.to_string_lossy().into_owned())
1175	            .unwrap_or_else(|| file.to_string());
1176	        groups.entry((short, basename)).or_default().push(i);
1177	    }
1178	    let mut out = Vec::new();
1179	    for ((fingerprint, basename), idxs) in &groups {
1180	        if idxs.len() < 2 {
1181	            continue;
1182	        }
1183	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1184	        out.push(dup_group_json(
1185	            "B",
1186	            &format!(
1187	                "suggestion fingerprint={} basename={}",
1188	                fingerprint, basename
1189	            ),
1190	            &refs,
1191	        ));
1192	    }
1193	    Ok(out)
1194	}
1195	
1196	fn find_duplicates_tier_c(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1197	    // Candidates: items with empty/missing symbol AND line > 0.
1198	    #[derive(Clone)]
1199	    struct Candidate {

1200	        idx: usize,
1201	        file: String,
1202	        line: i64,
1203	    }
1204	    let mut by_file: HashMap<String, Vec<Candidate>> = HashMap::new();
1205	    for (i, item) in items.iter().enumerate() {
1206	        let tbl = match item.as_table() {
1207	            Some(t) => t,
1208	            None => continue,
1209	        };
1210	        let symbol = tbl.get("symbol").and_then(|v| v.as_str()).unwrap_or("");
1211	        if !symbol.is_empty() {
1212	            continue;
1213	        }
1214	        let line = tbl.get("line").and_then(|v| v.as_integer()).unwrap_or(0);
1215	        if line <= 0 {
1216	            continue;
1217	        }
1218	        let file = tbl
1219	            .get("file")
1220	            .and_then(|v| v.as_str())
1221	            .unwrap_or("")
1222	            .to_string();
1223	        by_file.entry(file.clone()).or_default().push(Candidate {
1224	            idx: i,
1225	            file,
1226	            line,
1227	        });
1228	    }
1229	
1230	    let mut out = Vec::new();
1231	    // Deterministic order: sort file keys.
1232	    let mut files: Vec<&String> = by_file.keys().collect();
1233	    files.sort();
1234	    for file in files {
1235	        let cands = &by_file[file];
1236	        // Sort by line then idx so sweep is deterministic.
1237	        let mut sorted: Vec<Candidate> = cands.clone();
1238	        sorted.sort_by(|a, b| a.line.cmp(&b.line).then(a.idx.cmp(&b.idx)));
1239	        let n = sorted.len();
1240	        let mut i = 0;
1241	        while i < n {
1242	            // Greedy: start a group at sorted[i], extend while every pair in
1243	            // the growing group satisfies |line_a - line_b| <= 10. Because
1244	            // items are sorted by line, the tightest constraint is between
1245	            // the group's min-line (sorted[i]) and the candidate's line.
1246	            let mut j = i + 1;
1247	            while j < n && sorted[j].line - sorted[i].line <= 10 {
1248	                j += 1;
1249	            }
1250	            if j - i >= 2 {
1251	                let refs: Vec<&TomlValue> = sorted[i..j].iter().map(|c| &items[c.idx]).collect();
1252	                out.push(dup_group_json(
1253	                    "C",
1254	                    &format!(
1255	                        "file={} line_window=[{}..{}]",
1256	                        sorted[i].file, sorted[i].line, sorted[j - 1].line
1257	                    ),
1258	                    &refs,
1259	                ));
1260	                i = j;
1261	            } else {
1262	                i += 1;
1263	            }
1264	        }
1265	    }
1266	    Ok(out)
1267	}
