1359	/// Extract the byte-content between `<!-- SHARED-BLOCK:NAME START -->` and
1360	/// `<!-- SHARED-BLOCK:NAME END -->` markers. Markers themselves are NOT
1361	/// included in the hash input. Inner lines are joined by `\n` (matching awk's
1362	/// default ORS), with every content line — including the last — followed by
1363	/// `\n`. Returns None if either marker is missing.
1364	fn extract_block(contents: &str, name: &str) -> Option<Vec<u8>> {
1365	    let start = format!("<!-- SHARED-BLOCK:{} START -->", name);
1366	    let end = format!("<!-- SHARED-BLOCK:{} END -->", name);
1367	    let mut in_block = false;
1368	    let mut saw_start = false;
1369	    let mut saw_end = false;
1370	    let mut out = Vec::new();
1371	    for line in contents.split('\n') {
1372	        if line == start {
1373	            in_block = true;
1374	            saw_start = true;
1375	            continue;
1376	        }
1377	        if line == end {
1378	            in_block = false;
1379	            saw_end = true;
1380	            continue;
1381	        }
1382	        if in_block {
1383	            out.extend_from_slice(line.as_bytes());
1384	            out.push(b'\n');
1385	        }
1386	    }
1387	    if saw_start && saw_end {
1388	        Some(out)
1389	    } else {
1390	        None
1391	    }
1392	}
